//! Replays the lifecycle's share of the oracle corpus: every case of a kind
//! this crate answers must get the answer upstream's TypeScript gave,
//! compared as text. The cases are read against the installed tree kept
//! under `fixtures/upstream/`. The corpus is regenerated by
//! `tools/oracle/refresh.sh`; nothing here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_harness::Harness;
use focus_js::json::stringify;
use focus_lifecycle::oracle::{KINDS, run_case};
use focus_lifecycle::workflow::Workflow;
use focus_workspace::Layout;
use focus_workspace::records::{Invoker, Selection};
use serde_json::{Value, json};

#[test]
fn every_lifecycle_case_gets_upstreams_answer() {
    let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
    // Nothing is written: the install is read where the fixtures keep it.
    let wf = Workflow::open(
        Layout::new(fixtures.join("upstream/installed/claude"), Harness::Claude),
        Selection {
            space: "default".to_owned(),
            intent: None,
            session_id: None,
            binding: None,
        },
        Invoker::default(),
    )
    .unwrap();
    let dir = fixtures.join("oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.split('\n').filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.split('\n').filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let (mut windows, mut floored, mut unfloored, mut merged, mut open) = (0, 0, 0, 0, 0);
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        let case: Value = focus_js::json::parse(line).unwrap();
        let kind = case["kind"].as_str().unwrap_or_default();
        if !KINDS.contains(&kind) {
            continue;
        }
        let out = run_case(&wf, &case);
        windows += 1;
        floored += usize::from(out["floor"].as_i64().is_some_and(|floor| floor >= 0));
        unfloored += usize::from(out["floor"] == -1);
        merged += usize::from(
            out["merged"]
                .as_array()
                .is_some_and(|units| !units.is_empty()),
        );
        open += usize::from(
            out["open"]
                .as_array()
                .is_some_and(|units| !units.is_empty()),
        );
        let got = stringify(&json!({ "id": case["id"], "out": out }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    // Enough cases, and enough of them on each side of every answer.
    assert!(
        windows >= 1900 && floored >= 1400 && unfloored >= 400,
        "{windows} {floored} {unfloored}"
    );
    assert!(merged >= 280 && open >= 580, "{merged} {open}");
    assert!(
        differing.is_empty(),
        "{} lifecycle cases differ from upstream; first:\n{}",
        differing.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
